def flatten_nested(items):
    """Flatten an arbitrarily nested list of integers into a flat list, preserving order."""
    def _flatten(lst):
        for item in lst:
            if isinstance(item, list):
                yield from _flatten(item)
            else:
                yield item
    return list(_flatten(items))
